/* ===== src/js/46-list.js ===== */
/* ==========================================================================
   List: one layout for every row of a list
   --------------------------------------------------------------------------
   A list's rows either all keep their value beside the title, or all put it under the title
   (aligned with its first letter). Row by row, a value that did not fit dropped while its
   neighbours kept theirs beside, and the list read as ragged. CSS cannot ask "does every row
   fit?", so this measures the list with SG.fit (05-fit.js) and writes data-fit on it:

     row     every value beside its title (titles and meta lines wrap between words)
     stack   every value under its title; the lead and the chevron or icon stay where they are

   It re-checks when the list's size changes (a rotation, the reader's text size, a font
   loading), when a list is added, and when the current row changes (its title turns bold, so
   it is wider). Without JS there is no data-fit and list.css falls back to a width rule.

   API   SG.list.fit()   re-check every list now
   ========================================================================== */
(function (SG) {
  'use strict';

  SG.fit.register('.list', {
    steps: ['row', 'stack'],
    /* in row mode a title or meta line that cannot keep 6rem and its whole words beside its value
       overflows its .list__main (list.css), and that is what is measured, row by row. Not the list
       itself: a framed list paints its frame over the rows with an overlay that sits on the border,
       2px outside the list's padding box, so the list always "overflows" by 2px */
    measure: '.list__row',
    /* a meta line of facts clips its inline overflow (it hides the dot that starts a line), so it is measured
       itself: a word that does not fit beside the value would not show in its .list__main */
    parts: '.list__row, .list__main, .list__meta[data-facts]',
    strict: true, /* a title that runs a pixel into the row's end padding has not fitted */
    attrs: ['aria-current', 'aria-pressed']
  });

  SG.list = { fit: SG.fit.update };
})((window.SG = window.SG || {}));
